/**
 * Idempotent seed SQL for the curriculum registries (`communicative_intents`, `skills`) and
 * the honest `course_source_localizations` coverage rows generated by `@langquest/locales`.
 * Complements `buildCatalogSeedSql()` from `@langquest/db` (languages, varieties, tracks,
 * model profiles). Every statement is `INSERT … ON CONFLICT DO UPDATE`.
 */
import { INTENTS, SKILLS, summariseCoverage } from '@langquest/curriculum';
import { sqlJsonb, sqlLiteral, sqlNullable, sqlTextArray } from '@langquest/db/seed/catalog-sql';
import { generateCourseSourceLocalizationRows, validateCourseSourceLocalizationRows, type CurriculumSeed } from '@langquest/locales';
import type { SourceLanguageCode } from '@langquest/contracts';

/** `communicative_intents` upserts from the curriculum registry. */
export function buildIntentsSeedSql(): string {
  const out: string[] = ['-- communicative_intents (from @langquest/curriculum INTENTS)'];
  for (const i of INTENTS) {
    const constraints = { ...i.responseConstraints, conceptId: i.conceptId, socialRisk: i.socialRisk, acceptableVariants: i.acceptableVariants, broaderIntentKeys: i.broaderIntentKeys };
    out.push(
      `insert into public.communicative_intents (intent_key, description, response_constraints, social_meaning, polarity, politeness, skill_keys) values (${sqlLiteral(i.intentKey)}, ${sqlLiteral(i.description)}, ${sqlJsonb(constraints)}, ${sqlLiteral(i.socialMeaning)}, ${sqlLiteral(i.polarity)}, ${sqlLiteral(i.politeness)}, ${sqlTextArray(i.skillKeys)})` +
        ' on conflict (intent_key) do update set description = excluded.description, response_constraints = excluded.response_constraints, social_meaning = excluded.social_meaning, polarity = excluded.polarity, politeness = excluded.politeness, skill_keys = excluded.skill_keys;',
    );
  }
  return out.join('\n') + '\n';
}

/** `skills` upserts from the curriculum registry. */
export function buildSkillsSeedSql(): string {
  const out: string[] = ['-- skills (from @langquest/curriculum SKILLS)'];
  for (const s of SKILLS) {
    out.push(
      `insert into public.skills (skill_key, descriptor, difficulty, target_language_id, cefr_can_do, can_do_statement, prerequisite_skill_keys) values (${sqlLiteral(s.skillKey)}, ${sqlLiteral(s.descriptor)}, ${s.difficulty}, null, ${sqlNullable(s.cefrCanDo)}, ${sqlLiteral(s.canDoStatement)}, ${sqlTextArray(s.prerequisites)})` +
        ' on conflict (skill_key) do update set descriptor = excluded.descriptor, difficulty = excluded.difficulty, cefr_can_do = excluded.cefr_can_do, can_do_statement = excluded.can_do_statement, prerequisite_skill_keys = excluded.prerequisite_skill_keys;',
    );
  }
  return out.join('\n') + '\n';
}

/** Curriculum seeds derived from the honest coverage summary (partial where AI drafts exist). */
export function curriculumSeedsFromCoverage(sources?: readonly SourceLanguageCode[]): CurriculumSeed[] {
  const summary = summariseCoverage(sources ? { sources } : {});
  return summary.rows
    .filter((r) => r.status === 'partial')
    .map((r) => ({ courseTrackId: r.courseTrackId, sourceLanguageCode: r.sourceLanguageCode, missionInstructionsPct: r.metrics.mission_instructions_pct, explanationsPct: r.metrics.explanations_pct, subtitlesPct: 0, audioOverlaysPct: 0, nativeReviewed: false }));
}

/**
 * `course_source_localizations` upserts for every (track, source) from the locales generator.
 * Never downgrades a row a reviewer already marked `complete`/`native_reviewed`.
 */
export function buildCoverageSeedSql(sources?: readonly SourceLanguageCode[]): string {
  const rows = validateCourseSourceLocalizationRows(generateCourseSourceLocalizationRows({ seeds: curriculumSeedsFromCoverage(sources), ...(sources ? { sourceLanguages: sources } : {}) }));
  const out: string[] = ['-- course_source_localizations (from @langquest/locales generateCourseSourceLocalizationRows + curriculum coverage)'];
  for (const r of rows) {
    out.push(
      `insert into public.course_source_localizations (course_track_id, source_language_code, status, metrics, native_reviewed, editorial_note_key, fallback_source_language_code) values (${sqlLiteral(r.course_track_id)}, ${sqlLiteral(r.source_language_code)}, ${sqlLiteral(r.status)}, ${sqlJsonb(r.metrics)}, ${r.native_reviewed ?? false}, ${sqlNullable(r.editorial_note_key)}, ${sqlNullable(r.fallback_source_language_code)})` +
        ' on conflict (course_track_id, source_language_code) do update set status = excluded.status, metrics = excluded.metrics, editorial_note_key = excluded.editorial_note_key, fallback_source_language_code = excluded.fallback_source_language_code where public.course_source_localizations.native_reviewed = false and public.course_source_localizations.status <> \'complete\';',
    );
  }
  return out.join('\n') + '\n';
}

export const countStatements = (sql: string): number => sql.split('\n').filter((l) => /^insert into/i.test(l)).length;
